design.compositionCss:
/* Red Pencil: original contact-sheet cinema deck. */
.sidebar{grid-template-columns:170px minmax(0,1fr);border-bottom:12px solid var(--weekly-mark)}
.sidebar nav{grid-template-columns:repeat(4,minmax(0,1fr));gap:7px}
.nav-item{min-height:58px;display:flex;align-items:center;gap:10px;border:1px solid var(--acid);border-left:5px solid var(--weekly-mark);padding:9px 12px}
.nav-item span{font-family:var(--condensed);font-size:26px;margin:0}
.topbar{border-bottom:1px solid var(--ink);padding:30px 0 25px}
.topbar h1{font-family:var(--display);font-size:clamp(42px,5vw,76px);letter-spacing:-.07em;max-width:980px}
.hero-grid:not(.daily-summary){grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.poster-focus{grid-column:1/-1;grid-row:auto;min-height:500px;border:0;border-left:16px solid var(--weekly-mark);padding:45px 42px}
.poster-focus h2{font-family:var(--display);font-size:clamp(76px,8.5vw,132px);line-height:.88;letter-spacing:-.075em;max-width:760px}
.poster-focus .hero-script{font-size:33px!important;max-width:570px}
.poster-focus .cinema-scene{width:45%;right:-2%;top:10%;transform:rotate(5deg);opacity:.5}
.hero-grid .stat-card{grid-column:auto;min-height:145px;display:block;border:1px solid var(--ink);border-top:8px solid var(--weekly-mark);padding:18px;background:var(--panel)}
.hero-grid .stat-card strong{font-family:var(--condensed);font-style:normal;font-size:58px;display:block;margin:8px 0}
.studio-programme{gap:12px;border:0}
.studio-programme button{border:1px solid var(--ink)!important;border-top:7px solid var(--weekly-mark)!important;padding:20px!important;background:var(--weekly-soft)}
.panel h2,.intro-panel h2{font-family:var(--display);letter-spacing:-.06em}
.module{border:1px solid var(--ink);border-top:9px solid var(--weekly-mark);padding:26px;box-shadow:4px 4px 0 var(--weekly-soft)}
.module h3{font-family:var(--display);font-size:28px}
.roadmap{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px;columns:auto}
.phase{min-height:260px;margin:0!important;border:1px solid var(--ink);border-top:9px solid var(--weekly-mark);padding:26px;background:var(--panel)}
.phase h3{font-family:var(--display);font-size:29px;letter-spacing:-.05em}
.resource-list{gap:12px}
.resource{border:1px solid var(--ink);border-left:9px solid var(--weekly-mark);padding:22px;box-shadow:4px 4px 0 var(--weekly-soft)}
.resource h3{font-family:var(--display);font-size:19px}
.evidence-card{border-top:7px solid var(--weekly-mark);padding:22px}
.cinema-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;border:0}
.cinema-film{border:1px solid var(--ink);padding:22px}
.film-cover{border-bottom:8px solid var(--weekly-mark);min-height:330px}
.journal-masthead h2{font-family:var(--display);font-size:clamp(76px,10vw,142px);line-height:.9}
.journal-masthead h2 em{font-family:var(--script);font-size:.84em}
.journal-deck{grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;border:0}
.diary-card:nth-child(n){border:1px solid var(--ink);border-top:10px solid var(--weekly-mark);padding:26px;box-shadow:5px 5px 0 var(--weekly-soft);margin:0}
.diary-card h3{font-family:var(--display);font-size:clamp(36px,4vw,56px)}
@media(max-width:1100px) and (min-width:761px){.sidebar nav{grid-template-columns:repeat(3,minmax(0,1fr))}.roadmap{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:760px){.sidebar{display:block;border-bottom:7px solid var(--weekly-mark)}.hero-grid:not(.daily-summary){grid-template-columns:1fr;gap:8px}.poster-focus{min-height:460px;padding:30px 22px;border-left:9px solid var(--weekly-mark)}.poster-focus h2{font-size:clamp(60px,15vw,84px);line-height:.94}.poster-focus .cinema-scene{width:62%;right:-10%;opacity:.3}.hero-grid .stat-card{min-height:100px;padding:16px}.hero-grid .stat-card strong{font-size:42px}.roadmap,.cinema-grid,.journal-deck{grid-template-columns:1fr;gap:18px}.phase{min-height:0}.resource{display:block}.journal-masthead h2{font-size:clamp(58px,14vw,88px)}.diary-card:nth-child(n){padding:22px}}
@media(max-width:400px){.topbar h1{font-size:38px}.poster-focus h2{font-size:58px}.poster-focus .cinema-scene{opacity:.22}.panel h2{font-size:28px}}
